-- ── RLS + product-role write GRANTs for the 7 tenant-scoped LMS lookups above
--    (historically 26_tenant-scope-lms-lookups.sql; GRANT ... TO lms_svc
--    moved to 04_roles_and_grants.sql, after lms_svc's CREATE ROLE) ──
DO $rls$
DECLARE
  t TEXT;
  tables TEXT[] := ARRAY[
    'lms.lead_stage','lms.lead_stage_outcome','lms.interaction_types',
    'lms.follow_up_statuses','lms.lead_sources',
    'marketing.marketing_platforms','marketing.campaign_statuses'
  ];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS org_isolation_policy ON %s', t);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_policy ON %s', t);
    EXECUTE format('DROP POLICY IF EXISTS admin_tenant_config_policy ON %s', t);
    EXECUTE format($p$CREATE POLICY org_isolation_policy ON %s AS PERMISSIVE FOR SELECT TO app_user
      USING (tenant_id = (SELECT tenant_id FROM entity.organizations
                          WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid))$p$, t);
    EXECUTE format($p$CREATE POLICY tenant_isolation_policy ON %s AS PERMISSIVE FOR SELECT TO tenant_admin
      USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)$p$, t);
    -- N-6 admin write (super_admin acting within a selected tenant via withTenantConfigTx)
    EXECUTE format($p$CREATE POLICY admin_tenant_config_policy ON %s AS PERMISSIVE FOR ALL TO app_user
      USING      (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)
      WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)$p$, t);
  END LOOP;
END $rls$;

-- ── iam.departments (Tier C) — tenant-scoped, org-derived read ────────
-- Normal users (app_user pool) set current_org_id, not current_tenant_id, so
-- read visibility is derived from the current org's tenant — same shape as the
-- lookup tables above. The widening block below adds the NOINHERIT service
-- logins (hr_svc/lms_svc/task_svc) to these policies automatically.
ALTER TABLE iam.departments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS org_isolation_policy       ON iam.departments;
DROP POLICY IF EXISTS tenant_isolation_policy    ON iam.departments;
DROP POLICY IF EXISTS admin_tenant_config_policy ON iam.departments;
CREATE POLICY org_isolation_policy ON iam.departments AS PERMISSIVE FOR SELECT TO app_user
  USING (tenant_id = (SELECT tenant_id FROM entity.organizations
                      WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid));
CREATE POLICY tenant_isolation_policy ON iam.departments AS PERMISSIVE FOR SELECT TO tenant_admin
  USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);
-- Writes stay within the actor's tenant (derived from current org). WHO may write
-- is enforced in the app layer (HR/tenant admin); RLS only fences the tenant.
CREATE POLICY admin_tenant_config_policy ON iam.departments AS PERMISSIVE FOR ALL TO app_user
  USING      (tenant_id = (SELECT tenant_id FROM entity.organizations
                           WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid))
  WITH CHECK (tenant_id = (SELECT tenant_id FROM entity.organizations
                           WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid));

-- ── iam.user_roles (Tier C) — global anchors + own-tenant roles ───────
-- Anchor roles (tenant_id IS NULL) are shared by every tenant and MUST always be
-- visible; tenant-specific roles are scoped like departments. SELECT-only here —
-- role rows are written by the seed / migrations (superuser, bypasses RLS); any
-- future in-app role management gets its own write policy in C3.
ALTER TABLE iam.user_roles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS org_isolation_policy    ON iam.user_roles;
DROP POLICY IF EXISTS tenant_isolation_policy ON iam.user_roles;
CREATE POLICY org_isolation_policy ON iam.user_roles AS PERMISSIVE FOR SELECT TO app_user
  USING (tenant_id IS NULL
         OR tenant_id = (SELECT tenant_id FROM entity.organizations
                         WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid));
CREATE POLICY tenant_isolation_policy ON iam.user_roles AS PERMISSIVE FOR SELECT TO tenant_admin
  USING (tenant_id IS NULL
         OR tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);

-- ── iam.capabilities (Tier C3) — global catalog, readable by all ──────
-- The catalog is platform-shipped and carries no tenant data, so every
-- authenticated pool may read it; nobody may write it from the app (writes are
-- seed/migration only, as superuser, which bypasses RLS).
ALTER TABLE iam.capabilities ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS catalog_read_policy ON iam.capabilities;
CREATE POLICY catalog_read_policy ON iam.capabilities AS PERMISSIVE FOR SELECT TO app_user, tenant_admin
  USING (TRUE);

-- ── iam.role_capabilities (Tier C3) — defaults + own-tenant overrides ─
-- Reads must see BOTH the platform defaults (tenant_id IS NULL) and the tenant's
-- own overrides, or fn_role_capability_matrix's precedence would silently
-- collapse to deny. Writes are override-only: the WITH CHECK pins tenant_id to
-- the admin-SELECTED tenant, so an admin can never edit a platform default or
-- some other tenant's grant — the worst they can do is shape the one tenant
-- they picked.
--
-- The write policy keys on app.current_tenant_id, exactly like the N-6
-- admin_tenant_config_policy on every other tenant-scoped config table above,
-- and is reached through @platform/db's withTenantConfigTx.
--
-- It previously derived the tenant from app.current_org_id via a subquery on
-- entity.organizations, which cannot work for the actor this policy exists to
-- serve. The Capability Matrix screen is super_admin-only and cross-tenant by
-- design, but entity.organizations has FORCE RLS and its org_isolation_policy
-- shows app_user only the orgs in iam.fn_user_active_orgs(current_user_id) — so
-- for any tenant the super_admin is not personally mapped into, that subquery
-- evaluated to NULL and every write failed the WITH CHECK. Keying on the
-- selected tenant directly removes the dependency on entity.organizations.
--
-- Still safe at runtime for the same reason the other N-6 policies are: the
-- product runtime (withRoleTx's app_user branch) sets app.current_org_id and
-- never app.current_tenant_id, so this predicate is NULL — no match — on that
-- path and grants nothing extra. Only the explicit admin tx sets it.
ALTER TABLE iam.role_capabilities ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS org_isolation_policy       ON iam.role_capabilities;
DROP POLICY IF EXISTS tenant_isolation_policy    ON iam.role_capabilities;
DROP POLICY IF EXISTS admin_tenant_config_policy ON iam.role_capabilities;
CREATE POLICY org_isolation_policy ON iam.role_capabilities AS PERMISSIVE FOR SELECT TO app_user
  USING (tenant_id IS NULL
         OR tenant_id = (SELECT tenant_id FROM entity.organizations
                         WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid));
CREATE POLICY tenant_isolation_policy ON iam.role_capabilities AS PERMISSIVE FOR SELECT TO tenant_admin
  USING (tenant_id IS NULL
         OR tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);
CREATE POLICY admin_tenant_config_policy ON iam.role_capabilities AS PERMISSIVE FOR ALL TO app_user
  USING      (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)
  WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);

-- ── comms.message_templates ─────────────────────────────────────────
-- Same "global defaults stay visible" shape as iam.role_capabilities above,
-- extended one level for org_id. A caller must see:
--   * platform-wide rows (tenant_id IS NULL),
--   * their tenant's rows aimed at every org (org_id IS NULL),
--   * their tenant's rows aimed specifically at their own org,
-- and nothing aimed at a sibling org. Resolution to a single winner
-- (org > tenant > global) is the caller's ORDER BY; RLS only bounds the
-- candidate set.
--
-- Critically the predicate admits NULL rather than equating it. A plain
-- `tenant_id = <uuid>` would evaluate NULL for every seeded global row and hide
-- the entire catalog — the outage _migrations/17_tenant_scope_lms_catalogs.sql
-- was written to repair. SELECT-only: the catalog is seeded and administered by
-- root_service, never written on the send path.
--
-- DEPENDENCY, easy to trip over: the org -> tenant subquery reads
-- entity.organizations, which is ITSELF RLS-protected by a policy keyed on
-- iam.fn_user_active_orgs(app.current_user_id). So this policy only resolves
-- when app.current_user_id is set too, not just app.current_org_id. withRoleTx
-- always sets both, so application reads are fine — but a hand-rolled psql
-- session that sets only current_org_id gets a silent ZERO rows, not an error.
-- Note that iam.role_capabilities above shares this shape and looks like proof
-- the pattern is safe; it is not, because every one of its rows is tenant_id
-- IS NULL, so its first branch always short-circuits and the subquery is never
-- actually exercised. This table has tenant-owned rows and does exercise it.
ALTER TABLE comms.message_templates ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS org_isolation_policy    ON comms.message_templates;
DROP POLICY IF EXISTS tenant_isolation_policy ON comms.message_templates;
CREATE POLICY org_isolation_policy ON comms.message_templates AS PERMISSIVE FOR SELECT TO app_user
  USING (NOT is_deleted
         AND (tenant_id IS NULL
              OR (tenant_id = (SELECT tenant_id FROM entity.organizations
                               WHERE id = NULLIF(current_setting('app.current_org_id', true), '')::uuid)
                  AND (org_id IS NULL
                       OR org_id = NULLIF(current_setting('app.current_org_id', true), '')::uuid))));
CREATE POLICY tenant_isolation_policy ON comms.message_templates AS PERMISSIVE FOR SELECT TO tenant_admin
  USING (NOT is_deleted
         AND (tenant_id IS NULL
              OR tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid));


-- Widen every RLS policy to also name the roles that are MEMBERS of the roles
-- it already targets.
--
-- 04_roles_and_grants.sql assumes a "TO app_user" policy matches any member of
-- app_user regardless of INHERIT. That is not how Postgres works: policy
-- applicability uses the INHERIT-respecting check (pg_has_role(..,'USAGE')),
-- not 'MEMBER'. Every service login is NOINHERIT, so no app_user policy applied
-- to any of them and every policy-protected table read back ZERO rows -- with no
-- error, which is why it surfaced as empty module/tool lists rather than a failure.
--
-- Naming the member roles explicitly restores policy enforcement while KEEPING
-- them NOINHERIT, so the per-product GRANT isolation is untouched: a role still
-- holds only the table privileges granted to it directly.
--
-- Idempotent: the target role set is recomputed from current membership on every
-- run, so re-running after adding a role or policy converges.

DO $$
DECLARE
  p         RECORD;
  new_roles TEXT;
BEGIN
  FOR p IN
    SELECT pol.polname,
           n.nspname,
           c.relname,
           ARRAY(SELECT rolname FROM pg_roles WHERE oid = ANY (pol.polroles)) AS roles
    FROM pg_policy pol
    JOIN pg_class     c ON c.oid = pol.polrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    -- polroles = {0} means TO PUBLIC, which already covers everyone.
    WHERE pol.polroles <> '{0}'::oid[]
  LOOP
    SELECT string_agg(DISTINCT quote_ident(role_name), ', ')
      INTO new_roles
      FROM (
        SELECT unnest(p.roles) AS role_name
        UNION
        SELECT r.rolname
        FROM pg_auth_members m
        JOIN pg_roles r ON r.oid = m.member
        JOIN pg_roles g ON g.oid = m.roleid
        WHERE g.rolname = ANY (p.roles)
      ) s;

    EXECUTE format('ALTER POLICY %I ON %I.%I TO %s',
                   p.polname, p.nspname, p.relname, new_roles);
  END LOOP;
END $$;

COMMIT;
